What does Reciprocal Rank Fusion produce for these two rankings (k=60)?
```python
def rrf_fuse(rankings, k=60):
    scores = {}
    for ranking in rankings:
        for rank, doc in enumerate(ranking):
            scores[doc] = scores.get(doc, 0.0) + 1.0 / (k + rank + 1)
    return sorted(scores.items(), key=lambda p: -p[1])
print([(d, round(s, 4)) for d, s in rrf_fuse([[2, 0, 1], [0, 3, 2]])])
```

How do you merge and deduplicate results from several rewritten queries, keeping the highest score?
```python
runs = [[('c1', 0.62), ('c2', 0.55)], [('c2', 0.71), ('c3', 0.40)], [('c1', 0.58)]]
best = {}
for results in runs:
    for cid, score in results:
        best[cid] = max(score, best.get(cid, 0.0))
print(sorted(best.items(), key=lambda p: -p[1]))
```

What are Recall@3, MRR and the reciprocal rank for these retrievals?
```python
def recall_at_k(ret, rel, k): return len(set(ret[:k]) & rel) / len(rel)
def rr(ret, rel):
    for i, d in enumerate(ret, 1):
        if d in rel: return 1 / i
    return 0.0
runs = [(['c3', 'c12', 'c7', 'c4'], {'c12', 'c4'}), (['a', 'b', 'c'], {'c'}), (['x', 'y'], {'z'})]
print(round(recall_at_k(*runs[0], 3), 2), round(sum(rr(r, s) for r, s in runs) / 3, 3), rr(*runs[1]) == 1/3)
```

What happens when you instantiate the abstract VectorStore directly, and what does a concrete adapter return?
```python
from abc import ABC, abstractmethod
class VectorStore(ABC):
    @abstractmethod
    def upsert(self, ids, embeddings): ...
    @abstractmethod
    def search(self, query, top_k): ...
class InMemory(VectorStore):
    def __init__(self): self.d = {}
    def upsert(self, ids, embeddings): self.d.update(zip(ids, embeddings))
    def search(self, query, top_k):
        dist = lambda v: sum((a - b) ** 2 for a, b in zip(query, v))
        return [k for k, _ in sorted(self.d.items(), key=lambda kv: dist(kv[1]))[:top_k]]
try:
    VectorStore()
except TypeError:
    print('abstract')
s = InMemory(); s.upsert(['a', 'b'], [[1, 0], [0, 1]])
print(s.search([0.9, 0.1], 1))
```

